import{_ as t,c as e,o as r,b2 as s}from"./chunks/framework.CUhoHPxN.js";const h=JSON.parse('{"title":"C7Descriptions（C7 描述列表）设计说明","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/specs/2026-05-07-c7-descriptions-design.md","filePath":"superpowers/specs/2026-05-07-c7-descriptions-design.md"}'),d={name:"superpowers/specs/2026-05-07-c7-descriptions-design.md"};function n(c,o,g,a,i,l){return r(),e("div",null,[...o[0]||(o[0]=[s('<h1 id="c7descriptions-c7-描述列表-设计说明" tabindex="-1">C7Descriptions（C7 描述列表）设计说明 <a class="header-anchor vp-link" href="#c7descriptions-c7-描述列表-设计说明" aria-label="Permalink to &quot;C7Descriptions（C7 描述列表）设计说明&quot;">​</a></h1><p><strong>日期</strong>：2026-05-07<br><strong>状态</strong>：已定稿（经 brainstorming 澄清与确认）<br><strong>依据</strong>：<code>原始需求/前端/C7描述列表.md</code> + 与调用方约定（Q&amp;A 结论）</p><hr><h2 id="_1-背景与目标" tabindex="-1">1. 背景与目标 <a class="header-anchor vp-link" href="#_1-背景与目标" aria-label="Permalink to &quot;1. 背景与目标&quot;">​</a></h2><p>详情页需以「描述列表」展示对象字段，并支持字典标签、图片、链接、复制等形态。目标：在 <strong><code>ElDescriptions</code></strong> 之上提供 <strong>配置驱动</strong> 的 <strong><code>C7Descriptions</code></strong>，减少重复模板代码。</p><hr><h2 id="_2-组件边界与对外-api" tabindex="-1">2. 组件边界与对外 API <a class="header-anchor vp-link" href="#_2-组件边界与对外-api" aria-label="Permalink to &quot;2. 组件边界与对外 API&quot;">​</a></h2><h3 id="_2-1-命名与注册" tabindex="-1">2.1 命名与注册 <a class="header-anchor vp-link" href="#_2-1-命名与注册" aria-label="Permalink to &quot;2.1 命名与注册&quot;">​</a></h3><ul><li>组件名：<strong><code>C7Descriptions</code></strong></li><li>位置：<code>quick-ui/src/packages/C7Descriptions/index.vue</code>（与其它 C7 包一致）</li><li>在 <strong><code>quick-ui/src/packages/index.js</code></strong> 中注册并导出。</li></ul><h3 id="_2-2-根节点与属性透传" tabindex="-1">2.2 根节点与属性透传 <a class="header-anchor vp-link" href="#_2-2-根节点与属性透传" aria-label="Permalink to &quot;2.2 根节点与属性透传&quot;">​</a></h3><ul><li>根节点为 <strong><code>ElDescriptions</code></strong>。</li><li><strong><code>defineOptions({ name: &#39;C7Descriptions&#39;, inheritAttrs: false })</code></strong></li><li>根 <strong><code>ElDescriptions</code> 上使用 <code>v-bind=&quot;$attrs&quot;</code></strong><br> 文档说明：<strong>除下文「显式 props」外，其余属性与 Element Plus <code>el-descriptions</code> 一致</strong>（如 <code>border</code>、<code>column</code>、<code>direction</code>、<code>size</code> 等）。</li></ul><h3 id="_2-3-显式-props-不占-attrs" tabindex="-1">2.3 显式 props（不占 attrs） <a class="header-anchor vp-link" href="#_2-3-显式-props-不占-attrs" aria-label="Permalink to &quot;2.3 显式 props（不占 attrs）&quot;">​</a></h3><div class="vp-table"><table><thead><tr><th>Prop</th><th>说明</th></tr></thead><tbody><tr><td><strong><code>data</code></strong></td><td>详情对象。实现时建议默认 <code>{}</code>，避免出现 <code>null</code> 时子层取值/插槽语义不一致；若传入 <code>null</code>，以「无数据对象」处理，点路径解析结果为 <code>undefined</code>。</td></tr><tr><td><strong><code>items</code></strong></td><td>列配置数组，见第 3 节。</td></tr><tr><td><strong><code>defaultEmptyText</code></strong></td><td><strong>非 <code>tag</code> 列</strong>在「展示空」时的默认文案，默认 <strong><code>&#39;暂无&#39;</code></strong>（与原始验收口径一致）。</td></tr></tbody></table></div><h3 id="_2-4-插槽转发" tabindex="-1">2.4 插槽转发 <a class="header-anchor vp-link" href="#_2-4-插槽转发" aria-label="Permalink to &quot;2.4 插槽转发&quot;">​</a></h3><ul><li><strong><code>title</code></strong>、<strong><code>extra</code></strong>：与 Element Plus 一致，绑定到 <strong><code>ElDescriptions</code></strong>。</li></ul><hr><h2 id="_3-items-列配置与渲染规则" tabindex="-1">3. <code>items[]</code> 列配置与渲染规则 <a class="header-anchor vp-link" href="#_3-items-列配置与渲染规则" aria-label="Permalink to &quot;3. `items[]` 列配置与渲染规则&quot;">​</a></h2><h3 id="_3-1-公共字段" tabindex="-1">3.1 公共字段 <a class="header-anchor vp-link" href="#_3-1-公共字段" aria-label="Permalink to &quot;3.1 公共字段&quot;">​</a></h3><ul><li><strong><code>prop</code></strong>：支持 <strong>点号路径</strong>（如 <code>user.name</code>），从 <strong><code>data</code></strong> 取值。</li><li><strong><code>label</code></strong>、<strong><code>span</code></strong>：及 <strong><code>el-descriptions-item</code></strong> 支持的其它合法属性，建议 <strong><code>v-bind</code> 到对应 item 根</strong>（与 EP 文档对齐）。</li><li><strong><code>columnType</code></strong>：驱动内置渲染类型，见 3.3。</li><li><strong><code>formatter(value, row, item)</code></strong>：可选；在默认文本、<code>copy</code> 等需要「展示串 / 复制串」的分支中按各节约定调用。</li><li><strong><code>emptyText</code></strong>：覆盖 <strong><code>defaultEmptyText</code></strong>，<strong>仅用于非 <code>tag</code> 列</strong>的空展示。</li><li><strong><code>slotName</code></strong>：若 <strong>有值</strong> 且父组件提供了同名具名插槽，则 <strong>优先走插槽</strong>，不再走 <code>columnType</code> 内置渲染。</li></ul><h3 id="_3-2-具名插槽作用域-已定稿" tabindex="-1">3.2 具名插槽作用域（已定稿） <a class="header-anchor vp-link" href="#_3-2-具名插槽作用域-已定稿" aria-label="Permalink to &quot;3.2 具名插槽作用域（已定稿）&quot;">​</a></h3><p>当使用 <strong><code>item.slotName</code></strong> 时，对应具名插槽作用域为：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" tabindex="0"><code><span class="line"><span>{ row, value, item }</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li><strong><code>row</code></strong> 与 <strong><code>data</code> 为同一引用</strong>（命名贴近表格习惯）。</li><li><strong><code>value</code></strong>：按 <strong><code>prop</code></strong>（含点路径）从 <strong><code>data</code></strong> 解析得到的当前值。</li><li><strong><code>item</code></strong>：当前列配置对象。</li></ul><h3 id="_3-3-columntype-分支" tabindex="-1">3.3 <code>columnType</code> 分支 <a class="header-anchor vp-link" href="#_3-3-columntype-分支" aria-label="Permalink to &quot;3.3 `columnType` 分支&quot;">​</a></h3><p><strong>优先级</strong>：<code>slotName</code> + 插槽存在 → <strong>插槽</strong>；否则按 <strong><code>columnType</code></strong>（缺省视为 <strong>文本</strong>）。</p><div class="vp-table"><table><thead><tr><th><code>columnType</code></th><th>行为</th></tr></thead><tbody><tr><td><strong><code>tag</code></strong></td><td><strong>始终挂载 <code>C7DictTag</code></strong>。<strong><code>:model-value</code></strong> 绑定为当前 <strong><code>prop</code> 解析值</strong>。列配置中与 <strong><code>C7DictTag</code></strong> 一致的字段 <strong>平铺在 <code>item</code> 上</strong>：<strong><code>options</code></strong>、<strong><code>separator</code></strong>、<strong><code>showValue</code></strong>、<strong><code>max</code></strong>、<strong><code>collapse</code></strong>、<strong><code>dictType</code></strong>、<strong><code>size</code></strong>、<strong><code>effect</code></strong>、<strong><code>round</code></strong> 等（以 <code>C7DictTag</code> 实际 props 为准）。<strong>不使用</strong> <code>defaultEmptyText</code> / <code>item.emptyText</code>；空态、未匹配等 <strong>完全遵循 <code>C7DictTag</code> 现有实现</strong>（含 <strong><code>-</code></strong>）。<strong>原始需求中的 <code>dictList</code> 不作为本组件正式 API</strong>，文档统一写 <strong><code>options</code></strong>（与 <code>C7DictTag</code> 一致）。</td></tr><tr><td><strong><code>image</code></strong></td><td>使用 <strong><code>ElImage</code></strong>；<strong><code>src</code></strong> 使用 <strong><code>prop</code> 解析值</strong>（字符串 URL）。扩展：允许 <strong><code>item.imageAttrs</code></strong> 对象 <strong><code>v-bind</code></strong> 到 <strong><code>ElImage</code></strong>（预览列表、teleport 等），首期实现以「能预览」为最低标准。</td></tr><tr><td><strong><code>link</code></strong></td><td>渲染 <strong><code>&lt;a&gt;</code></strong>。字段：<strong><code>linkHref</code></strong>（字符串，首期不支持函数）、<strong><code>linkText</code></strong>、<strong><code>linkTarget</code></strong>。<strong><code>linkText</code> 缺省</strong>时：使用经 <strong><code>formatter</code></strong>（若有）后的展示串，否则对 <strong><code>value</code></strong> 做合理字符串化。<strong>展示空</strong>时走 3.4，不输出可点击链接或输出禁用样式由实现与 EP 习惯择一，<strong>须在实现注释中写死一种</strong>。</td></tr><tr><td><strong><code>copy</code></strong> / <strong><code>copyable</code></strong></td><td>内嵌 <strong><code>C7Copy</code></strong>。<strong>复制文本</strong>：优先 <strong><code>formatter</code></strong> 返回值（若为字符串可用语义），否则 <strong><code>String(value)</code></strong>（<strong><code>null</code>/<code>undefined</code></strong> 视为空串）。<strong><code>C7Copy</code> 的其余 props</strong>：通过 <strong><code>item.copyProps</code></strong> 对象传入并 <strong><code>v-bind</code></strong>，避免与列公共字段命名冲突。</td></tr><tr><td><strong>默认 / 其它</strong></td><td>纯文本展示：先 <strong><code>formatter</code></strong>，再字符串化；<strong>展示空</strong>见 3.4。</td></tr></tbody></table></div><h3 id="_3-4-「展示空」判定-仅非-tag-列" tabindex="-1">3.4 「展示空」判定（仅非 <code>tag</code> 列） <a class="header-anchor vp-link" href="#_3-4-「展示空」判定-仅非-tag-列" aria-label="Permalink to &quot;3.4 「展示空」判定（仅非 `tag` 列）&quot;">​</a></h3><p>用于决定是否显示 <strong><code>item.emptyText ?? defaultEmptyText</code></strong>：</p><ul><li><strong>首期</strong>：<strong><code>null</code></strong>、<strong><code>undefined</code></strong>、<strong><code>&#39;&#39;</code></strong> 视为展示空。</li><li><strong><code>[]</code></strong>：<strong>首期不</strong>视为空（避免与多值语义混淆）；若产品后续要求，可单列变更。</li></ul><h3 id="_3-5-点路径与健壮性" tabindex="-1">3.5 点路径与健壮性 <a class="header-anchor vp-link" href="#_3-5-点路径与健壮性" aria-label="Permalink to &quot;3.5 点路径与健壮性&quot;">​</a></h3><ul><li>取值使用 <strong><code>lodash-es/get</code></strong> 或与项目表格列 <strong>一致的</strong> 工具函数。</li><li><strong><code>prop</code> 缺失或路径不存在</strong>：得到 <strong><code>undefined</code></strong>，走空值分支；<strong>不向业务抛异常</strong>。</li><li><strong>未知 <code>columnType</code></strong>：按 <strong>文本</strong> 渲染；可选：<strong>开发环境</strong>对未知类型 <strong><code>console.warn</code> 一次</strong>（实现期决定是否开启）。</li></ul><hr><h2 id="_4-方案结论-实现结构" tabindex="-1">4. 方案结论（实现结构） <a class="header-anchor vp-link" href="#_4-方案结论-实现结构" aria-label="Permalink to &quot;4. 方案结论（实现结构）&quot;">​</a></h2><ul><li><strong>推荐</strong>：单文件 <strong><code>C7Descriptions/index.vue</code></strong> + 少量纯函数（点路径取值、是否展示空、分支渲染）。若单文件过长，再抽 <strong><code>useDescriptionCell</code></strong> 等，<strong>首期不强制拆分</strong>。</li></ul><hr><h2 id="_5-测试与验收" tabindex="-1">5. 测试与验收 <a class="header-anchor vp-link" href="#_5-测试与验收" aria-label="Permalink to &quot;5. 测试与验收&quot;">​</a></h2><ul><li><strong>点路径</strong>：嵌套字段能正确显示。</li><li><strong>非 <code>tag</code> 列空值</strong>：显示 <strong><code>暂无</code></strong>（或配置的 <strong><code>defaultEmptyText</code> / <code>emptyText</code></strong>）。</li><li><strong><code>tag</code> 列</strong>：与单独使用 <strong><code>C7DictTag</code></strong> 时行为一致（含 <strong><code>-</code></strong> 空态）。</li><li><strong>各 <code>columnType</code></strong>：至少覆盖一条用例（含 <strong><code>copyProps</code></strong>、<strong><code>imageAttrs</code></strong> 可选 smoke）。</li><li><strong>插槽</strong>：<code>slotName</code> 插槽能拿到 <strong><code>{ row, value, item }</code></strong>，且 <strong><code>row === data</code></strong>。</li></ul><hr><h2 id="_6-澄清记录-q-a" tabindex="-1">6. 澄清记录（Q&amp;A） <a class="header-anchor vp-link" href="#_6-澄清记录-q-a" aria-label="Permalink to &quot;6. 澄清记录（Q&amp;A）&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>主题</th><th>结论</th></tr></thead><tbody><tr><td><code>tag</code> 与 <code>C7DictTag</code></td><td><strong><code>columnType: &#39;tag&#39;</code> 内部复用 <code>C7DictTag</code></strong>，<strong><code>options</code></strong> 等与 <code>C7DictTag</code> 对齐。</td></tr><tr><td>空值与「暂无」</td><td><strong><code>tag</code> 列不适用</strong> <code>defaultEmptyText</code> / <code>emptyText</code>；<strong>其它列</strong>适用 <strong><code>defaultEmptyText</code>（默认「暂无」）</strong> 与 <strong><code>item.emptyText</code></strong>。</td></tr><tr><td><code>ElDescriptions</code> 其它属性</td><td><strong><code>inheritAttrs: false</code> + 根 <code>v-bind=&quot;$attrs&quot;</code></strong>，与 EP 文档一致。</td></tr><tr><td>插槽作用域</td><td><strong><code>{ row, value, item }</code></strong>，<strong><code>row</code> 与 <code>data</code> 同一引用</strong>。</td></tr></tbody></table></div><hr><h2 id="_7-自检说明-定稿前已核对" tabindex="-1">7. 自检说明（定稿前已核对） <a class="header-anchor vp-link" href="#_7-自检说明-定稿前已核对" aria-label="Permalink to &quot;7. 自检说明（定稿前已核对）&quot;">​</a></h2><ul><li><strong>无 TBD</strong>：首期 <strong><code>linkHref</code> 仅为字符串</strong>；<strong><code>[]</code> 非空</strong> 已写明。</li><li><strong>一致性</strong>：<strong><code>tag</code></strong> 与 <strong><code>emptyText</code></strong> 职责不交叉；<strong><code>dictList</code></strong> 已明确不作为 API。</li><li><strong>范围</strong>：单组件 + 注册导出；<strong>不</strong>包含修改 <strong><code>C7DictTag</code></strong> 行为。</li><li><strong>歧义</strong>：<strong><code>copy</code></strong> 的额外参数统一走 <strong><code>copyProps</code></strong>；<strong><code>image</code></strong> 扩展走 <strong><code>imageAttrs</code></strong>。</li></ul>',43)])])}const u=t(d,[["render",n]]);export{h as __pageData,u as default};
